settings.custom_liquid:
{% liquid
  assign rating = product.metafields.reviews.rating.value
  assign rating_count = product.metafields.reviews.rating_count.value | default: 0 | plus: 0
  assign rating_max = rating.scale_max | default: 5 | plus: 0

  assign rating_value = 0
  if rating != blank and rating_max > 0
    assign rating_value = rating.rating | times: 5.0 | divided_by: rating_max
  endif
%}

<div class="tyt-title-mobile">

  <!-- Product Title -->
  <h1 class="tyt-title-mobile__heading">
    {{ product.title | escape }}
  </h1>

  <!-- Product Subtitle -->
  {% if product.metafields.custom.product_subtitle != blank %}
    <p class="tyt-title-mobile__subtitle">
      {{ product.metafields.custom.product_subtitle.value | escape }}
    </p>
  {% endif %}

  <!-- Shopify Native Rating -->
  {% if rating != blank and rating_count > 0 %}

    <a class="tyt-rating-mobile" href="#looxReviewsFrame">

      <span class="tyt-rating-mobile__stars" aria-hidden="true">

        {% for i in (1..5) %}
          {% assign star_fill = rating_value | minus: forloop.index0 %}

          {% if star_fill >= 1 %}
            {% assign star_percent = 100 %}
          {% elsif star_fill > 0 %}
            {% assign star_percent = star_fill | times: 100 | round %}
          {% else %}
            {% assign star_percent = 0 %}
          {% endif %}

          <span class="tyt-rating-mobile__star"
            style="--star-fill: {{ star_percent }}%;">
            <svg viewBox="0 0 24 24">
              <path class="star-bg"
                d="M12 2.5l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.3l-5.8 3.1 1.1-6.5-4.7-4.6 6.5-.9z"/>
              <path class="star-fill"
                d="M12 2.5l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.3l-5.8 3.1 1.1-6.5-4.7-4.6 6.5-.9z"/>
            </svg>
          </span>
        {% endfor %}

      </span>

      <span class="tyt-rating-mobile__value">
        {{ rating_value | round: 1 }}
      </span>

      <span class="tyt-rating-mobile__count">
        ({{ rating_count }} reviews)
      </span>

    </a>

  {% endif %}

</div>

<style>
  .tyt-title-mobile {
    display: none;
  }

  @media screen and (max-width: 749px) {

    .tyt-title-mobile {
      display: block;
      width: 100%;
      box-sizing: border-box;
      padding: 10px 12px;
      margin: 0;
      color: #1a1a1a;
      background-color: #ffffff;
      border: none;
      border-radius: 6px;
    }

    .tyt-title-mobile__heading {
    margin: 0;
    font-family: var(--font-body-family);
    font-style: normal;
      font-size: 22px;
      line-height: 1.3;
      font-weight: 700;
      letter-spacing: -0.2px;
      color: #1a1a1a;
      overflow-wrap: break-word;
    }

    .tyt-title-mobile__subtitle {
      margin: 5px 0 0;
      padding: 0;
      color: #777777;
      font-size: 14px;
      line-height: 1.35;
      font-weight: 400;
      overflow-wrap: break-word;
    }

    .tyt-rating-mobile {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin-top: 8px;
      padding: 0;
      color: #555555;
      text-decoration: none;
      line-height: 1;
    }

    .tyt-rating-mobile__stars {
      display: inline-flex;
      align-items: center;
      gap: 2px;
    }

    .tyt-rating-mobile__star {
      display: inline-block;
      width: 16px;
      height: 16px;
      flex: 0 0 16px;
    }

    .tyt-rating-mobile__star svg {
      display: block;
      width: 16px;
      height: 16px;
      overflow: visible;
    }

    .tyt-rating-mobile__star .star-bg {
      fill: #e2e2e2;
    }

    .tyt-rating-mobile__star .star-fill {
      fill: #f5a623;
      clip-path: inset(0 calc(100% - var(--star-fill)) 0 0);
    }

    .tyt-rating-mobile__value {
      font-size: 13px;
      font-weight: 600;
      color: #333333;
    }

    .tyt-rating-mobile__count {
      font-size: 13px;
      color: #777777;
    }
  }
</style>

{% liquid
  assign rating = product.metafields.reviews.rating.value
  assign rating_count = product.metafields.reviews.rating_count.value | default: 0 | plus: 0
  assign rating_max = rating.scale_max | default: 5 | plus: 0

  assign rating_value = 0

  if rating != blank and rating_max > 0
    assign rating_value = rating.rating | times: 5.0 | divided_by: rating_max
  endif
%}

<div class="tyt-title-desktop">

  <!-- Product Title -->
  <h1 class="tyt-title-desktop__heading">
    {{ product.title | escape }}
  </h1>

  <!-- Product Subtitle -->
  {% if product.metafields.custom.product_subtitle != blank %}
    <p class="tyt-title-desktop__subtitle">
      {{ product.metafields.custom.product_subtitle.value | escape }}
    </p>
  {% endif %}

  <!-- Shopify Standard Star Rating -->
  {% if rating != blank and rating_count > 0 %}

    <a
      class="tyt-rating-desktop"
      href="#looxReviewsFrame"
      aria-label="Rated {{ rating_value | round: 1 }} out of 5 based on {{ rating_count }} reviews"
    >

      <span class="tyt-rating-desktop__stars" aria-hidden="true">

        {% for i in (1..5) %}

          {% assign star_fill = rating_value | minus: forloop.index0 %}

          {% if star_fill >= 1 %}
            {% assign star_percent = 100 %}
          {% elsif star_fill > 0 %}
            {% assign star_percent = star_fill | times: 100 | round %}
          {% else %}
            {% assign star_percent = 0 %}
          {% endif %}

          <span
            class="tyt-rating-desktop__star"
            style="--star-fill: {{ star_percent }}%;"
          >

            <span class="tyt-rating-desktop__star-base">
              <svg viewBox="0 0 24 24">
                <path d="M12 2.5l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.3l-5.8 3.1 1.1-6.5-4.7-4.6 6.5-.9z"/>
              </svg>
            </span>

            <span class="tyt-rating-desktop__star-fill">
              <svg viewBox="0 0 24 24">
                <path d="M12 2.5l2.9 5.9 6.5.9-4.7 4.6 1.1 6.5L12 17.3l-5.8 3.1 1.1-6.5-4.7-4.6 6.5-.9z"/>
              </svg>
            </span>

          </span>

        {% endfor %}

      </span>

      <span class="tyt-rating-desktop__value">
        {{ rating_value | round: 1 }}
      </span>

      <span class="tyt-rating-desktop__count">
        ({{ rating_count }} reviews)
      </span>

    </a>

  {% endif %}

</div>

<style>
  /* Desktop Product Title Container */

  .tyt-title-desktop {
    display: block;
    width: 100%;
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  /* Product Title */

  .tyt-title-desktop__heading {
    margin: 0;
    font-family: var(--font-body-family);
    font-style: normal;
    font-size: 40px;
    color: #000000;
    font-weight: 400;
    line-height: 1.4;
    letter-spacing: normal;
    overflow-wrap: break-word;
  }

  /* Product Subtitle */

  .tyt-title-desktop__subtitle {
    margin: 5px 0 0;
    padding: 0;
    color: #777777;
    font-size: 14px;
    line-height: 1.35;
    font-weight: 400;
    letter-spacing: 0;
    overflow-wrap: break-word;
  }

  /* Star Rating */

  .tyt-rating-desktop {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 7px;
    margin: 8px 0 12px;
    padding: 0;
    color: #555555;
    text-decoration: none;
    line-height: 1;
  }

  .tyt-rating-desktop__stars {
    display: inline-flex;
    align-items: center;
    gap: 3px;
  }

  .tyt-rating-desktop__star {
    position: relative;
    display: inline-block;
    width: 19px;
    height: 19px;
    flex: 0 0 19px;
  }

  .tyt-rating-desktop__star-base,
  .tyt-rating-desktop__star-fill {
    position: absolute;
    top: 0;
    left: 0;
    height: 19px;
    overflow: hidden;
  }

  .tyt-rating-desktop__star-base {
    width: 19px;
  }

  .tyt-rating-desktop__star-fill {
    width: var(--star-fill);
  }

  .tyt-rating-desktop__star svg {
    display: block;
    width: 19px;
    height: 19px;
    fill: #e2e2e2;
  }

  .tyt-rating-desktop__star-fill svg {
    fill: #f5a623;
  }

  .tyt-rating-desktop__value {
    font-size: 14px;
    font-weight: 600;
    color: #333333;
  }

  .tyt-rating-desktop__count {
    font-size: 14px;
    font-weight: 400;
    color: #777777;
  }

  .tyt-rating-desktop:hover {
    text-decoration: underline;
  }

  /* Hide on Mobile */

  @media screen and (max-width: 749px) {
    .tyt-title-desktop {
      display: none;
    }
  }
</style>

{% liquid
  assign ninety_days_seconds = 7776000
  assign deadline_timestamp = 'now' | date: '%s' | plus: ninety_days_seconds

  assign target_year = deadline_timestamp | date: '%Y' | plus: 0
  assign target_month = deadline_timestamp | date: '%m' | plus: 0

  assign next_month = target_month | plus: 1
  assign next_year = target_year

  if next_month > 12
    assign next_month = 1
    assign next_year = target_year | plus: 1
  endif

  if next_month < 10
    assign next_month_string = next_month | prepend: '0'
  else
    assign next_month_string = next_month
  endif

  assign next_month_start = next_year | append: '-' | append: next_month_string | append: '-01'
  assign target_month_end = next_month_start | date: '%s' | minus: 86400
  assign current_month_start = deadline_timestamp | date: '%Y-%m-01'
  assign previous_month_end = current_month_start | date: '%s' | minus: 86400

  if target_month_end <= deadline_timestamp
    assign exchange_deadline_timestamp = target_month_end
  else
    assign exchange_deadline_timestamp = previous_month_end
  endif

  assign exchange_deadline = exchange_deadline_timestamp | date: '%B %d, %Y'
%}

<div class="tyt-service-bar">

  <!-- Delivery -->
  <div class="tyt-service-bar__item">

    <svg viewBox="0 0 24 24" aria-hidden="true">
      <path d="M2.5 5.5h12v12h-12z"/>
      <path d="M14.5 9h4l3 3.5v5h-7z"/>
      <circle cx="7" cy="18.5" r="2"/>
      <circle cx="18" cy="18.5" r="2"/>
      <path d="M14.5 12.5h7"/>
    </svg>

    <div class="tyt-service-bar__text">
      <span>Delivered Within</span>
      <strong class="tyt-service-bar__highlight">
        5 Business Days
      </strong>
    </div>

  </div>

  <!-- Free Shipping -->
  <div class="tyt-service-bar__item">

    <svg viewBox="0 0 24 24" aria-hidden="true">
      <path d="M12 22s8-7.2 8-13a8 8 0 1 0-16 0c0 5.8 8 13 8 13z"/>
      <circle cx="12" cy="9" r="2.5"/>
    </svg>

    <div class="tyt-service-bar__text">
      <strong class="tyt-service-bar__highlight">
        Free Shipping
      </strong>
      <span>in the Contiguous U.S.</span>
    </div>

  </div>

  <!-- Free Exchanges -->
  <div class="tyt-service-bar__item">

    <svg viewBox="0 0 24 24" aria-hidden="true">
      <path d="M20 7h-9a7 7 0 0 0-7 7"/>
      <path d="m16 3 4 4-4 4"/>
      <path d="M4 17h9a7 7 0 0 0 7-7"/>
      <path d="m8 21-4-4 4-4"/>
    </svg>

    <div class="tyt-service-bar__text">
      <span>Free Exchanges Until</span>
      <strong class="tyt-service-bar__highlight">
        {{ exchange_deadline }}
      </strong>
    </div>

  </div>

</div>

<style>
  .tyt-service-bar {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    width: 100%;
    margin: 0;
    padding: 10px 0;
    box-sizing: border-box;
  }

  .tyt-service-bar * {
    box-sizing: border-box;
  }

  /* Individual Items */

  .tyt-service-bar__item {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-width: 0;
    padding: 6px 12px;
    border-right: 1px solid #eeeeee;
  }

  .tyt-service-bar__item:last-child {
    border-right: none;
  }

  /* SVG Icons */

  .tyt-service-bar__item svg {
    display: block;
    width: 25px;
    height: 25px;
    flex: 0 0 25px;
    fill: none;
    stroke: #C9252C;
    stroke-width: 1.7;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* Text */

  .tyt-service-bar__text {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
    color: #666666;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.4;
  }

  .tyt-service-bar__text span {
    display: block;
  }

  /* Highlight All Three Benefits */

  .tyt-service-bar__highlight {
    display: block;
    color: #C9252C;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.3;
  }

  /* Mobile */

  @media screen and (max-width: 749px) {

    .tyt-service-bar {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      padding: 10px 0;
    }

    .tyt-service-bar__item {
      flex-direction: column;
      justify-content: flex-start;
      align-items: center;
      gap: 7px;
      padding: 5px 6px;
      text-align: center;
    }

    .tyt-service-bar__item svg {
      width: 23px;
      height: 23px;
      flex-basis: 23px;
    }

    .tyt-service-bar__text {
      align-items: center;
      gap: 3px;
      font-size: 12px;
      line-height: 1.35;
      text-align: center;
    }

    .tyt-service-bar__highlight {
      font-size: 13px;
      font-weight: 700;
      line-height: 1.3;
    }

  }
</style>

{% if product.description != blank %}

<div
  id="tyt-description-{{ section.id }}-{{ product.id }}"
  class="tyt-description"
>

  <!-- Description Content -->
  <div
    class="tyt-description__content is-collapsed"
    data-tyt-description-content
  >
    {{ product.description }}
  </div>

  <!-- Minimal Read More Button -->
  <div
    class="tyt-description__footer"
    data-tyt-description-footer
    hidden
  >
    <button
      type="button"
      class="tyt-description__toggle"
      data-tyt-description-toggle
      aria-expanded="false"
      aria-controls="tyt-description-content-{{ section.id }}-{{ product.id }}"
    >
      <span class="tyt-description__label">
        Read More
      </span>

      <svg
        class="tyt-description__arrow"
        viewBox="0 0 24 24"
        width="14"
        height="14"
        fill="none"
        aria-hidden="true"
      >
        <path
          d="M6 9L12 15L18 9"
          stroke="currentColor"
          stroke-width="1.6"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
    </button>
  </div>

</div>

<style>

  /* Main Container */

  #tyt-description-{{ section.id }}-{{ product.id }} {
    width: 100%;
    margin: 0;
    padding: 0;
    color: inherit;
    box-sizing: border-box;
  }

  #tyt-description-{{ section.id }}-{{ product.id }} * {
    box-sizing: border-box;
  }

  /* Description Text */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__content {
    width: 100%;
    font-size: 14px;
    line-height: 1.6;
    color: #555555;
    position: relative;
  }

  /* Three Line Preview */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__content.is-collapsed {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    overflow: hidden;
  }

  /* Bottom Fade */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__content.is-collapsed::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 14px;
    background: linear-gradient(
      to bottom,
      rgba(255,255,255,0),
      rgba(255,255,255,0.85)
    );
    pointer-events: none;
  }

  /* Footer */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__footer {
    display: flex;
    justify-content: center;
    width: 100%;
    margin-top: 5px;
    padding: 0;
    border: none;
  }

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__footer[hidden] {
    display: none !important;
  }

  /* Minimal Button */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 5px;

    padding: 4px 0;
    margin: 0;

    border: none;
    outline: none;
    background: transparent;
    box-shadow: none;

    color: #999999;
    font-family: inherit;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.3px;

    cursor: pointer;

    transition: color 0.2s ease;
  }

  /* Arrow */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__arrow {
    display: block;
    flex-shrink: 0;
    color: #aaaaaa;
    transition: transform 0.25s ease;
  }

  /* Hover */

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__toggle:hover {
    color: #666666;
  }

  #tyt-description-{{ section.id }}-{{ product.id }}
  .tyt-description__toggle:hover
  .tyt-description__arrow {
    color: #666666;
  }

  /* Expanded */

  #tyt-description-{{ section.id }}-{{ product.id }}.is-expanded
  .tyt-description__content {
    display: block;
    overflow: visible;
  }

  #tyt-description-{{ section.id }}-{{ product.id }}.is-expanded
  .tyt-description__content::after {
    display: none;
  }

  #tyt-description-{{ section.id }}-{{ product.id }}.is-expanded
  .tyt-description__arrow {
    transform: rotate(180deg);
  }

  /* Mobile */

  @media screen and (max-width: 749px) {

    #tyt-description-{{ section.id }}-{{ product.id }}
    .tyt-description__content {
      font-size: 13px;
      line-height: 1.55;
    }

    #tyt-description-{{ section.id }}-{{ product.id }}
    .tyt-description__footer {
      margin-top: 4px;
    }

    #tyt-description-{{ section.id }}-{{ product.id }}
    .tyt-description__toggle {
      font-size: 10px;
      gap: 4px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    #tyt-description-{{ section.id }}-{{ product.id }}
    .tyt-description__arrow {
      transition: none;
    }
  }

</style>

<script>
(function () {

  const root = document.getElementById(
    'tyt-description-{{ section.id }}-{{ product.id }}'
  );

  if (!root || root.dataset.initialized === 'true') return;

  const content = root.querySelector(
    '[data-tyt-description-content]'
  );

  const footer = root.querySelector(
    '[data-tyt-description-footer]'
  );

  const button = root.querySelector(
    '[data-tyt-description-toggle]'
  );

  const label = root.querySelector(
    '.tyt-description__label'
  );

  if (!content || !footer || !button || !label) return;

  root.dataset.initialized = 'true';

  content.id = 'tyt-description-content-{{ section.id }}-{{ product.id }}';

  let resizeTimer = null;

  // Update interface according to current state
  function setExpanded(expanded) {

    button.setAttribute(
      'aria-expanded',
      expanded ? 'true' : 'false'
    );

    if (expanded) {

      content.classList.remove('is-collapsed');
      root.classList.add('is-expanded');
      label.textContent = 'Show Less';

    } else {

      content.classList.add('is-collapsed');
      root.classList.remove('is-expanded');
      label.textContent = 'Read More';

    }

  }

  // Check whether description needs Read More
  function checkDescription() {

    // Preserve current interaction state
    const wasExpanded =
      button.getAttribute('aria-expanded') === 'true';

    // Remove expanded state before measuring
    root.classList.remove('is-expanded');
    content.classList.add('is-collapsed');

    // Measure collapsed and full heights
    const collapsedHeight = content.clientHeight;
    const fullHeight = content.scrollHeight;

    const hasMore = fullHeight > collapsedHeight + 2;

    if (!hasMore) {

      // No need for Read More
      content.classList.remove('is-collapsed');
      root.classList.remove('is-expanded');

      footer.hidden = true;

      button.setAttribute('aria-expanded', 'false');
      label.textContent = 'Read More';

      return;
    }

    // Show button when content exceeds three lines
    footer.hidden = false;

    // Restore previous state
    // Automatic checks must never collapse expanded content
    setExpanded(wasExpanded);

  }

  // User click interaction
  button.addEventListener('click', function () {

    const expanded =
      button.getAttribute('aria-expanded') === 'true';

    // Only user interaction changes expanded state
    setExpanded(!expanded);

  });

  // Initial measurement
  requestAnimationFrame(checkDescription);

  // Recheck after images load
  content.querySelectorAll('img').forEach(function (img) {

    if (!img.complete) {

      img.addEventListener(
        'load',
        checkDescription,
        { once: true }
      );

      img.addEventListener(
        'error',
        checkDescription,
        { once: true }
      );

    }

  });

  // Recheck on window resize
  window.addEventListener('resize', function () {

    clearTimeout(resizeTimer);

    resizeTimer = setTimeout(function () {
      checkDescription();
    }, 150);

  });

  // Shopify theme editor support
  document.addEventListener(
    'shopify:section:load',
    function (event) {

      if (event.target.contains(root)) {
        checkDescription();
      }

    }
  );

})();
</script>

{% endif %}
